// Use the original cua API to get the app state
let b = await cua.getBrowser({ extensionInstanceId: 'fixture-extension' });
let state = await cua.getState();

// Check available browsers and tabs
state.browsers.length;

const apps = await cua.listApps();
const chromeApp = apps.find(a => a.displayName && a.displayName.toLowerCase().includes('chrome'));
console.log("Found Chrome app:", chromeApp);

if (chromeApp) {
  const app = await cua.getApp(chromeApp.displayName);
  const { state, screenshot } = await app.getAXStateAndScreenshot({ disableDiffing: true });
  console.log("Got state and screenshot");
  console.log("State length:", state.length);
  console.log("Screenshot size:", screenshot ? screenshot.length : 0);

  // Print first part of state to see what's on screen
  console.log("State preview:");
  console.log(state.substring(0, 500));

  state.substring(0, 1000);
} else {
  "Chrome app not found";
}

const state = await cua.getState();
console.log("Available apps:");
state.apps.forEach(a => {
  if (a.displayName && a.displayName.includes('Chrome')) {
    console.log(`  ${a.id} - ${a.displayName}`);
  }
});

// Also check browsers
console.log("\nAvailable browsers:");
state.browsers.forEach(b => {
  console.log(`  ${b.id} - ${b.name} (${b.family})`);
  b.tabs.forEach((t, i) => {
    console.log(`    Tab ${i}: ${t.url}`);
  });
});

"State retrieved";

// Search for "teapot" on the MDN status codes page
await cua.getState().then(async state => {
  const tab = await cua.getTab({ url: 'https://developer.mozilla.org/en-US/docs/Web/HTTP/Status' }, { browser: 'fixture-extension' });
